pitfalls.badSnippet:
// Independent angles create a visual crease at (midX, midY)
ctx.bezierCurveTo(cp1X, cp1Y, cp2X, cp2Y, midX, midY);
ctx.bezierCurveTo(randX, randY, cp4X, cp4Y, endX, endY);

pitfalls.goodSnippet:
// Ensure incoming CP₂, anchor P, and outgoing CP₁ are strictly collinear
ctx.bezierCurveTo(cp1X, cp1Y, midX - dx, midY - dy, midX, midY);
ctx.bezierCurveTo(midX + dx, midY + dy, cp4X, cp4Y, endX, endY);
